"""Live local dashboard for the paired baseline experiment and physics cohort."""
from pathlib import Path
import json
import argparse


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--root',type=Path,default=Path('outputs/results/semantic_baselines_long_v2'));args=parser.parse_args()
    root=args.root.resolve()
    out=Path('outputs/results/grasp_fix_web/planar/baselines');out.mkdir(parents=True,exist_ok=True)
    for name in ('progress.json','protocol.json','summary.json','contacts.json','baseline_comparison.png','baseline_comparison.svg'):
        p=out/name
        if p.is_symlink():p.unlink()
        if not p.exists():p.symlink_to(root/name)
    media=out/'physics';media.mkdir(exist_ok=True)
    spec=json.loads((root/'protocol.json').read_text())
    for cell in spec['cells']:
        if cell['seed']==0 and cell['allowed']:
            for method in spec['methods']:
                p=media/(cell['id']+'__'+method+'.html')
                if p.is_symlink():p.unlink()
                if not p.exists():p.symlink_to(root/cell['id']/method/'dynamics/scene.html')
    page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>语义 GCS 长实验：三个方法公平对照</title><style>body{margin:0;background:#f1f5f9;color:#24364c;font:16px/1.7 system-ui}main{max-width:1240px;margin:auto;padding:24px}.card{padding:22px;background:white;border-radius:12px;margin:16px 0}h1{font-size:28px}table{width:100%;border-collapse:collapse}td,th{padding:10px;text-align:left;border-bottom:1px solid #dce4ec}progress{width:100%;height:22px}select,button{font:inherit;padding:8px}a{color:#087a85}iframe{width:100%;height:650px;border:0}.notice{border-left:5px solid #087a85}svg{width:100%;height:280px}.small{font-size:14px;color:#52677c}</style><main>
<h1>同一语义任务：B1、B2 与联合 GCS 长实验</h1><div class="card notice"><strong id="headline">正在读取实验进度</strong><progress id="progress" max="108" value="0"></progress><p id="active"></p><p class="small">页面每 10 秒更新。运行期间只是阶段性结果，不能据此判断方法胜负。失败、超时、未完成枚举都会保留。</p></div>
<div class="card"><strong>提前固定的比较协议</strong><p>3 个起点 × 4 种抓取动作可用性 × 3 个取整种子，共 36 组配对条件、108 次独立方法运行。每方法每组 300 秒预算，共用候选库、凸区域、代价和完整轨迹审计；各方法独立求解，不借用其他方法的结果。</p><table><tr><th>方法</th><th>选择策略</th></tr><tr><td>B1 顺序选择</td><td>按预先固定的 x 升序逐候选规划，第一个完整审计通过即停止。</td></tr><tr><td>B2 枚举比较</td><td>逐候选规划，在预算内保留最低代价的已审计方案；未枚举完会明确标注。</td></tr><tr><td>联合 GCS</td><td>同时选择抓取候选及前后连续路径，使用凸松弛和有限取整。</td></tr></table><p>这是同一物理场景的 9 种正例起点/语义条件，各用 3 个种子；另外 9 组配对负例禁用全部抓取动作。不是 36 个独立随机场景。区域与原语准备历史测得约 41 秒，主表比较复用共同库后的规划成本，不冒称完整冷启动性能。</p></div>
<div class="card"><h2>主结果：正例单独统计</h2><table><thead><tr><th>方法</th><th>已审计成功 / 已完成正例</th><th>超时</th><th>总耗时中位数</th><th>首次可行解中位数</th><th>B2 完整枚举</th></tr></thead><tbody id="metrics"></tbody></table><p id="paired"></p><p id="selection"></p><p class="small">超时但已有通过审计的方案，计为成功且保留超时标记；耗时按 300 秒截断。首次可行解统计仅包含成功运行。路径质量只在三种方法均有合法解的配对条件下比较，不把失败当作零代价。</p><h3>相同时间预算下，能提供合法方案的次数</h3><svg id="chart" viewBox="0 0 900 260"></svg><p id="negatives"></p></div>
<div class="card"><h2>逐组核对</h2><select id="case"></select><table><thead><tr><th>方法</th><th>状态</th><th>候选</th><th>已审计路径代价</th><th>非预期接触 / 执行</th></tr></thead><tbody id="caseRows"></tbody></table><p id="mediaButtons"></p><p id="mediaLabel"></p><iframe id="viewer" title="预先选定条件的接触仿真" hidden></iframe><p class="small">接触执行预先选定 seed 0 的全部 9 个正例条件 × 3 个方法，共 27 个结果；无合法规划的保留为未执行，执行失败如实展示。每条仅一次自由杯子力驱动仿真，非硬件或鲁棒性成功率验证。</p></div>
<div class="card"><a href="protocol.json">冻结协议与输入哈希</a> · <a href="progress.json">全部运行记录与最好解历史</a> · <a href="summary.json">汇总数据</a> · <a href="baseline_comparison.svg">实验图 SVG（最终完成后）</a> · <a href="contacts.json">接触执行数据</a> · <a href="../candidates/">此前单场景候选实验</a><p>目标是加权配置空间路径长度，不是能耗；B2 是枚举得到的最好可行结果，非全局最优真值。密集碰撞审计不是连续安全证明，IRIS 库仍有已知抽样碰撞。</p></div></main>
<script>const methods=['B1_first_valid','B2_enumerate','joint_gcs'],names={B1_first_valid:'B1 顺序选择',B2_enumerate:'B2 枚举比较',joint_gcs:'联合 GCS'},colors=['#2880c4','#0d957a','#dd7b25'];let P,S,C={runs:[]};const med=a=>a.length?a.sort((a,b)=>a-b)[Math.floor(a.length/2)]:null,fmt=x=>x===null||x===undefined?'—':x.toFixed(2),valid=r=>r.best&&r.best.discovered_seconds<=300;function row(id,values){const tr=document.createElement('tr');for(const v of values){const td=document.createElement('td');td.textContent=v;tr.append(td)}document.getElementById(id).append(tr)}
function group(){const k=document.getElementById('case').value;document.getElementById('caseRows').replaceChildren();document.getElementById('mediaButtons').replaceChildren();for(const m of methods){const r=P.runs.find(r=>r.cell===k&&r.method===m),c=(C.runs||[]).find(c=>c.cell===k&&c.method===m);row('caseRows',[names[m],r?r.status:'待完成',r&&r.best?r.best.candidate:'—',r&&valid(r)?fmt(r.best.cost):'—',c?(c.result?c.result.unexpected_contact_count+' / '+c.status:c.status):'尚无接触结果']);if(c&&c.output){const b=document.createElement('button');b.textContent=names[m]+' 接触回放';b.onclick=()=>{const v=document.getElementById('viewer');v.hidden=false;v.src='physics/'+k+'__'+m+'.html';document.getElementById('mediaLabel').textContent=names[m]+' · 本次自由杯子接触执行：'+c.status};document.getElementById('mediaButtons').append(b)}}}
function chart(){const svg=document.getElementById('chart');svg.replaceChildren();function el(t,a){const e=document.createElementNS('http://www.w3.org/2000/svg',t);for(const[k,v]of Object.entries(a))e.setAttribute(k,v);svg.append(e);return e}const budgets=[10,30,60,120,300],x=t=>65+(t/300)*650,y=n=>215-n/27*175;el('path',{d:'M65 35 V215 H735',fill:'none',stroke:'#8493a4'});for(const t of budgets)el('text',{x:x(t),y:238,'font-size':13,'text-anchor':'middle'}).textContent=t+'s';for(const n of [0,9,18,27])el('text',{x:48,y:y(n)+4,'font-size':13,'text-anchor':'end'}).textContent=n;methods.forEach((m,i)=>{const rows=P.runs.filter(r=>r.method===m&&r.allowed&&r.allowed.length);const points=budgets.map(t=>[x(t),y(rows.filter(r=>(r.incumbent_history||[]).some(h=>h.seconds<=t)).length)]);el('polyline',{points:points.map(p=>p.join(',')).join(' '),fill:'none',stroke:colors[i],'stroke-width':3});el('text',{x:750,y:65+30*i,fill:colors[i],'font-size':14}).textContent=names[m]})}
async function update(){try{P=await(await fetch('progress.json?t='+Date.now())).json();S=await(await fetch('protocol.json')).json();try{C=await(await fetch('contacts.json?t='+Date.now())).json()}catch{}document.getElementById('headline').textContent=`规划完成 ${P.completed}/${P.total}；接触执行记录 ${C.completed||0}/27`;document.getElementById('progress').value=P.completed;document.getElementById('active').textContent='正在运行：'+(Object.keys(P.active).join('，')||'规划阶段已结束');document.getElementById('metrics').replaceChildren();for(const m of methods){const a=P.runs.filter(r=>r.method===m&&r.allowed&&r.allowed.length),v=a.filter(valid);row('metrics',[names[m],v.length+' / '+a.length,a.filter(r=>r.timed_out).length,fmt(med(a.map(r=>Math.min(r.parent_wall_seconds,300))))+' s',fmt(med(v.map(r=>r.incumbent_history[0].seconds)))+' s',m==='B2_enumerate'?a.filter(r=>r.enumeration_complete).length+' / '+a.length:'—'])}const paired=[];let sameCandidate=0;for(const cell of S.cells.filter(c=>c.allowed.length)){const rows=methods.map(m=>P.runs.find(r=>r.cell===cell.id&&r.method===m));if(rows.every(r=>r&&valid(r))){paired.push(rows[2].best.cost/rows[1].best.cost-1);if(rows[2].best.candidate===rows[0].best.candidate)sameCandidate++}}document.getElementById('paired').textContent=`三种方法均成功的配对条件：${paired.length}；联合 GCS 相对 B2 的代价差中位数：${paired.length?fmt(100*med(paired))+'%':'待形成配对结果'}（正数表示联合方法代价更高，不是最优性 gap）。`;document.getElementById('selection').textContent=`联合 GCS 与 B1 选择同一抓取候选：${sameCandidate}/${paired.length}。路径代价的差异未必来自语义动作选择，也可能来自几何路径取整。`;const neg=P.runs.filter(r=>r.allowed&&!r.allowed.length);document.getElementById('negatives').textContent=`结构负例：${neg.filter(r=>r.status==='unreachable_in_compiled_graph').length}/${neg.length} 正确拒绝，与正例成功率分开。`;const select=document.getElementById('case');if(!select.options.length)for(const c of S.cells){const o=document.createElement('option');o.value=c.id;o.textContent=`起点 (${c.start[0]}, ${c.start[1]})｜可用候选 ${c.allowed.join(', ')||'无'}｜种子 ${c.seed}`;select.append(o)}chart();group()}catch(e){document.getElementById('headline').textContent='结果文件尚未就绪：'+e.message}}document.getElementById('case').onchange=()=>{document.getElementById('viewer').hidden=true;document.getElementById('viewer').src='about:blank';document.getElementById('mediaLabel').textContent='';group()};update();setInterval(update,10000);</script></html>'''
    # Use the conventional median, including averaging the middle two samples.
    page=page.replace("a.sort((a,b)=>a-b)[Math.floor(a.length/2)]", "((a.sort((a,b)=>a-b)[Math.floor((a.length-1)/2)]+a[Math.floor(a.length/2)])/2)")
    (out/'index.html').write_text(page)
    print(out/'index.html')


if __name__=='__main__':main()
